import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { ca: readFileSync('/etc/ssl/rds-ca.pem') }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  // In production this verifies JWT signature
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
  req.tenantId = payload.tenant_id;
  req.userId = payload.sub;
  next();
}

// Search endpoint with dynamic filtering
app.post('/api/v2/reports/search', extractTenant, async (req, res) => {
  try {
    const { filters, sort_by, limit } = req.body;
    const params = [req.tenantId];
    let paramIdx = 2;

    let query = `SELECT r.id, r.title, r.created_at, r.status, r.summary 
                 FROM reports r WHERE r.tenant_id = $1`;

    // Apply user-provided filters
    if (filters) {
      for (const [field, value] of Object.entries(filters)) {
        // Allowlist check for filter fields
        const allowed = ['status', 'created_after', 'created_before', 'author_id', 'department'];
        if (!allowed.includes(field)) continue;

        if (field === 'created_after') {
          query += ` AND r.created_at >= $${paramIdx}`;
          params.push(value);
          paramIdx++;
        } else if (field === 'created_before') {
          query += ` AND r.created_at <= $${paramIdx}`;
          params.push(value);
          paramIdx++;
        } else {
          query += ` AND r.${field} = $${paramIdx}`;
          params.push(value);
          paramIdx++;
        }
      }
    }

    // Sort - user controlled, validated against allowlist
    const sortAllowed = ['created_at', 'title', 'status', 'id'];
    const sortField = sortAllowed.includes(sort_by) ? sort_by : 'created_at';
    query += ` ORDER BY r.${sortField} DESC`;

    // Limit with cap
    const safeLimit = Math.min(parseInt(limit) || 25, 100);
    query += ` LIMIT ${safeLimit}`;

    const result = await pool.query(query, params);
    res.json({ reports: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Export endpoint - generates CSV with user-controlled column selection
app.post('/api/v2/reports/export', extractTenant, async (req, res) => {
  try {
    const { columns, report_ids } = req.body;

    if (!Array.isArray(report_ids) || report_ids.length === 0) {
      return res.status(400).json({ error: 'report_ids required' });
    }
    if (report_ids.length > 500) {
      return res.status(400).json({ error: 'max 500 reports per export' });
    }

    // Build column list from user input
    const requestedCols = Array.isArray(columns) ? columns : ['id', 'title', 'status'];

    // Construct query with user-specified columns
    const colList = requestedCols.join(', ');
    const placeholders = report_ids.map((_, i) => `$${i + 2}`).join(', ');

    const query = `SELECT ${colList} FROM reports WHERE tenant_id = $1 AND id IN (${placeholders})`;
    const params = [req.tenantId, ...report_ids];

    const result = await pool.query(query, params);

    // Format as CSV
    const header = requestedCols.join(',');
    const rows = result.rows.map(row => requestedCols.map(c => JSON.stringify(row[c] ?? '')).join(','));
    const csv = [header, ...rows].join('\n');

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename=export_${Date.now()}.csv`);
    res.send(csv);
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('Report service listening on :3000'));
